use std::fs

fn parse_line(line: string) -> string {
    let mut chars = Vec::new()
    for ch in line.chars() {
        chars.push(ch.to_string())
    }
    let n = chars.len()
    let mut out = ""
    let mut count = 1
    let mut cur = ""
    let mut inq = false
    let mut i = 0
    while i < n {
        let c = chars[i]
        if inq {
            if c == "\"" {
                if i + 1 < n && chars[i + 1] == "\"" {
                    cur = cur + "\""
                    i += 1
                } else {
                    inq = false
                }
            } else {
                cur = cur + c
            }
        } else if c == "\"" {
            inq = true
        } else if c == "," {
            out = out + "[" + cur + "]|"
            cur = ""
            count += 1
        } else {
            cur = cur + c
        }
        i += 1
    }
    out = out + "[" + cur + "]"
    count.to_string() + ": " + out
}

fn main() {
    let input = match fs::read_to_string("/dev/stdin") {
        Ok(s) => s,
        Err(_) => "",
    }
    let lines = input.split("\n")
    let mut v = Vec::new()
    for l in lines {
        v.push(l.replace("\r", ""))
    }
    let mut total = v.len()
    if total > 0 && v[total - 1] == "" {
        total -= 1
    }
    let mut k = 0
    while k < total {
        println(parse_line(v[k]))
        k += 1
    }
}

